// I am going to finish building the house with the collected planks.
let pos = bot.entity.position;

// Define the dimensions of the house
const width = 5;
const depth = 6;
const height = 4;

// Calculate the starting positions for building the walls
let startX = Math.floor(pos.x) - Math.floor(width / 2);
let startZ = Math.floor(pos.z) - Math.floor(depth / 2);

// Build the roof
for (let x = startX; x < startX + width; x++) {
    for (let z = startZ; z < startZ + depth; z++) {
        await skills.placeBlock(bot, 'oak_planks', x, pos.y + height, z);
    }
}

// Place a door
await skills.placeBlock(bot, 'oak_door', startX + Math.floor(width / 2), pos.y, startZ + depth - 1, 'south');

console.log("House finished with Nepenthic!");```
